package com.wuzz.shimmer

import android.animation.ValueAnimator
import android.content.Context
import android.graphics.*
import android.view.animation.LinearInterpolator
import com.margelo.nitro.core.HybridView

// HybridShimmerViewSpec is generated by `npx nitrogen`.
class HybridShimmerView(context: Context) : HybridShimmerViewSpec(context) {

  // MARK: - Drawing state
  private val paint    = Paint(Paint.ANTI_ALIAS_FLAG)
  private val matrix   = Matrix()
  private val drawRect = RectF()           // pre-allocated — never allocate inside onDraw
  private var gradient: LinearGradient? = null
  private var offset   = 0f

  private val shimmerWidthPx: Float
    get() = 160f * resources.displayMetrics.density

  // MARK: - Animator
  private var animator: ValueAnimator? = null

  // MARK: - Nitro props

  override var duration: Double = 1800.0
    set(value) { field = value; restartAnimation() }

  override var borderRadius: Double = 0.0

  override var shimmerColor: String = "#E0E0E0"
    set(value) {
      field = value
      try { setBackgroundColor(Color.parseColor(value)) } catch (_: Exception) {}
    }

  override var highlightOpacity: Double = 0.7
    set(value) { field = value; buildGradient() }

  // MARK: - Init

  init {
    // Hardware layer → GPU-composited drawing, no software rasterisation per frame
    setLayerType(LAYER_TYPE_HARDWARE, null)
    try { setBackgroundColor(Color.parseColor(shimmerColor)) } catch (_: Exception) {}
  }

  // MARK: - Layout

  override fun onSizeChanged(w: Int, h: Int, oldw: Int, oldh: Int) {
    super.onSizeChanged(w, h, oldw, oldh)
    buildGradient()
    restartAnimation()
  }

  private fun buildGradient() {
    if (width <= 0) return
    val op = highlightOpacity.toFloat()
    gradient = LinearGradient(
      0f, 0f, shimmerWidthPx, 0f,
      intArrayOf(
        Color.argb(0,   255, 255, 255),
        Color.argb((op * 0.4f * 255).toInt(), 255, 255, 255),
        Color.argb((op * 255).toInt(),        255, 255, 255),
        Color.argb((op * 0.4f * 255).toInt(), 255, 255, 255),
        Color.argb(0,   255, 255, 255),
      ),
      floatArrayOf(0f, 0.2f, 0.5f, 0.8f, 1f),
      Shader.TileMode.CLAMP
    )
    paint.shader = gradient
  }

  // MARK: - Animation

  private fun restartAnimation() {
    animator?.cancel()
    if (width <= 0) return

    val sw = shimmerWidthPx
    animator = ValueAnimator.ofFloat(-sw, width + sw).apply {
      this.duration    = this@HybridShimmerView.duration.toLong()
      repeatCount      = ValueAnimator.INFINITE
      repeatMode       = ValueAnimator.RESTART
      interpolator     = LinearInterpolator()
      addUpdateListener { anim ->
        offset = anim.animatedValue as Float
        // Move gradient via matrix — no new object allocation per frame
        matrix.setTranslate(offset, 0f)
        gradient?.setLocalMatrix(matrix)
        invalidate()
      }
      start()
    }
  }

  // MARK: - Draw

  override fun onDraw(canvas: Canvas) {
    super.onDraw(canvas)
    if (gradient == null) return
    val r = (borderRadius * resources.displayMetrics.density).toFloat()
    drawRect.set(0f, 0f, width.toFloat(), height.toFloat())
    if (r > 0f) canvas.drawRoundRect(drawRect, r, r, paint)
    else        canvas.drawRect(drawRect, paint)
  }

  // MARK: - Lifecycle

  override fun onAttachedToWindow() {
    super.onAttachedToWindow()
    restartAnimation()
  }

  override fun onDetachedFromWindow() {
    super.onDetachedFromWindow()
    animator?.removeAllUpdateListeners()
    animator?.cancel()
    animator = null
  }
}
